custom_css:
/* 一本笔记本@夜行性鲨鱼
   禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎……给我吃一口吧！
   带符号🤍的地方是可以自定义的区域 */
/*此版本为song的粉紫色二改*/

@import url("https://fontsapi.zeoseven.com/371/main/result.css");

body,#bg1{margin:0!important;padding:0!important;background-color:transparent!important}
/* 全局字体 - 巴别石汉 */
body, #chat .mes .mes_text, #chat .mes .name_text, #send_textarea, .menu_button, .text_pole, textarea, select, .drawer-content, .standoutHeader, .title_restorable, .inline-drawer-header, #toast-container>.toast, .mes_reasoning, .ch_name {
    font-family: "BabelStone Han", "PingFang SC", "Microsoft YaHei", sans-serif !important;
}

/* 代码块保持原样不变 */
pre, code, .hljs {
    font-family: monospace !important;
}
::-webkit-scrollbar{display:none}
#sheld,#form_sheld,.top-bar-border{border:none!important;box-shadow:none!important;background:transparent!important}
/* 核心精修：增加上下自然渐隐蒙版 */
#chat{border:none!important;box-shadow:none!important;background:transparent!important;padding-top:25px!important;padding-bottom:80px!important;gap:40px!important;-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 30px),transparent 100%)!important;mask-image:linear-gradient(to bottom,transparent 0,#000 25px,#000 calc(100% - 30px),transparent 100%)!important}

/* 1.核心气泡 - 粉紫主题 */
#chat .mes{position:relative!important;background:#fff9fc!important;width:93%!important;max-width:860px!important;margin:0 auto!important;padding:30px 35px 40px 50px!important;border:1px solid #fbe5f0!important;border-radius:4px 12px 12px 4px!important;box-shadow:-2px 0 5px rgba(0,0,0,0.02),1px 1px 0 #fff0f5,2px 2px 0 #fae6f0,3px 3px 0 #f5dce8,4px 4px 10px rgba(0,0,0,0.06)!important;display:flex!important;flex-direction:column!important;overflow:visible!important}
#chat .mes::after{display:none!important}
/* 装订线左侧装饰 - 粉紫 */
#chat .mes::before{content:""!important;display:block!important;position:absolute!important;left:8px!important;top:20px!important;bottom:20px!important;width:32px!important;background:transparent!important;background-image:repeating-linear-gradient(to bottom,transparent 0,transparent 18px,#f0c0d8 18px,#fff9fc 19px,#d9a6c4 20px,transparent 21px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 21px,#f0c0d8 21px,#fff9fc 22px,#d9a6c4 23px,transparent 24px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 16px,#e8b8d0 16px,#f5d0e4 17px,#f5d0e4 25px,#e8b8d0 26px,transparent 26px,transparent 40px),repeating-linear-gradient(to bottom,transparent 0,transparent 17px,#b582a0 17px,#c9a0bc 25px,transparent 25px,transparent 40px)!important;background-size:32px 100%,32px 100%,12px 100%,10px 100%!important;background-position:0 0,0 0,20px 0,21px 0!important;background-repeat:repeat-y!important;z-index:10}

/* 🤍2.内容包裹 - 替换为粉紫色图片示例 */
#chat .mes .mes_block{display:flex!important;flex-direction:column!important;width:100%!important;padding-left:25px!important;box-sizing:border-box!important;margin:0!important;background:transparent!important;box-shadow:-15px 0 15px -15px rgba(0,0,0,0.05)!important}
#chat .mes .mes_block::before{content:"";display:block;width:100%;height:180px;border-radius:8px;background:url("https://iili.io/BS18mjn.jpg") center/cover no-repeat;margin-bottom:25px}
#chat .mes[is_user="true"] .mes_block::before{background-image:url("https://image.uglycat.cc/vdo5r7.jpg")!important}

/* 3.头像与悬浮 */
#chat .mes .mesAvatarWrapper{position:absolute!important;top:0!important;left:0!important;width:100%!important;height:100%!important;pointer-events:none!important}
#chat .mes .avatar{position:absolute!important;top:165px!important;left:110px!important;width:70px!important;height:70px!important;border-radius:50%!important;border:4px solid #fff9fc!important;background:#fff9fc!important;box-shadow:0 4px 10px rgba(0,0,0,0.08)!important;pointer-events:auto!important;padding:0!important;z-index:5}
#chat .mes .avatar img{width:100%!important;height:100%!important;border-radius:50%!important;object-fit:cover!important}
#chat .mes .avatar::before,#chat .mes .avatar::after{display:none!important}

/* 🤍4.角色名+自定义文本 */
#chat .mes .ch_name{display:flex!important;flex-direction:column!important;margin-left:125px!important;margin-top:-10px!important;padding:0!important;min-height:auto!important;background:transparent!important;border:none!important;overflow:visible!important}
#chat .mes .ch_name .alignItemsBaseline{display:flex!important;flex-direction:row!important;align-items:center!important;gap:6px!important}
#chat .mes .name_text::before{content:"@";color:#b582a0;font-weight:500;font-size:19px!important;margin-right:4px}
#chat .mes .name_text{font-size:20px!important;font-weight:700!important;color:#6b4c5c!important;letter-spacing:.5px!important;margin:0!important;display:flex;align-items:center}
#chat .mes .timestamp{display:inline-block!important;position:static!important;font-size:12px!important;color:#c9a0bc!important;margin:0 0 0 4px!important}
/* 🤍 自定义装饰文字 */
#chat .mes .ch_name>.flex-container.flex1::after{content:"第一个相遇，在晨曦洒落的幽径上，一朵花告诉了我它的名字。";white-space:pre-wrap;display:block;font-size:13.5px;color:#b582a0;line-height:1.5;margin-top:6px;letter-spacing:.5px}
#chat .mes .ch_name .alignItemsBaseline::after{display:none!important}

/* 5.数据位置：粉紫文字美化 */
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{position:absolute!important;top:195px!important;font-size:11px!important;color:#fff0f5!important;background:transparent!important;border:none!important;box-shadow:none!important;line-height:1!important;pointer-events:auto!important;margin:0!important;z-index:6;font-weight:800!important;letter-spacing:.5px!important;-webkit-text-stroke:.3px rgba(80,50,70,.4)!important;text-shadow:0 0 2px #b582a0,0 0 4px rgba(130,80,110,.8),0 2px 6px rgba(80,50,70,.5)!important}
#chat .mes .tokenCounterDisplay{right:45px!important}
#chat .mes .mes_timer{right:110px!important}
#chat .mes .mesIDDisplay{right:175px!important}

/* 6.按钮-修复菜单显示与溢出 - 粉紫调 */
#chat .mes .mes_buttons{position:absolute!important;bottom:20px!important;right:40px!important;top:auto!important;width:auto!important;height:auto!important;z-index:11;pointer-events:auto;display:flex!important;flex-direction:row!important;gap:15px!important;overflow:visible!important}
#chat .mes .mes_buttons .mes_button{display:none!important;position:relative!important;font-size:16px!important;color:#e0b8d0!important;opacity:0;transition:opacity .2s;cursor:pointer}
#chat .mes:hover .mes_buttons .mes_button{opacity:1}
#chat .mes .mes_buttons .mes_button:hover{color:#b582a0!important}
#chat .mes .mes_buttons .extraMesButtonsHint,#chat .mes .mes_buttons .mes_bookmark,#chat .mes .mes_buttons .mes_edit{display:block!important}
#chat .mes .mes_buttons .extraMesButtons{display:none;position:absolute;bottom:30px;right:0;background:#fff9fc!important;border:1px solid #fbe5f0!important;border-radius:8px;padding:8px 12px!important;box-shadow:0 4px 15px rgba(0,0,0,0.1);z-index:99;flex-direction:row!important;gap:12px!important;width:max-content}
#chat .mes .mes_buttons .extraMesButtons .mes_button{display:block!important;opacity:1!important;color:#c9a0bc!important}


/* 7.正文与思维链排版 - 粉紫文本装饰 */
#chat .mes .mes_text{background-color:transparent!important;width:100%!important;margin:40px 0 0 0!important;padding:0!important;color:#5e4a58!important;line-height:1.9!important;border:none!important;font-size:14.5px!important}
#chat .mes .mes_text::before,#chat .mes .mes_text::after{display:none!important}
#chat .mes .mes_text p{margin-bottom:15px!important;text-align:justify}
#chat .mes .mes_text q{quotes:none;background:rgba(200,160,180,.15);color:#6b4c5c;padding:1px 4px;margin:0 3px;border-radius:2px;border-bottom:1px solid #e0b8d0;font-weight:500;transition:.2s}
#chat .mes .mes_text q:hover{background:rgba(200,160,180,.25)}
#chat .mes .mes_text strong{position:relative!important;z-index:1!important;color:#6b4c5c!important;font-weight:700!important;background:linear-gradient(to bottom,transparent 60%,rgba(200,160,180,.3) 40%)!important}
#chat .mes .mes_text em{position:relative!important;padding-left:1.2em!important;font-style:italic!important;color:#b582a0!important;display:inline!important}
#chat .mes .mes_text em::before{content:""!important;position:absolute!important;left:0!important;top:0.12em!important;width:1em!important;height:1em!important;background:url("https://iili.io/BSW9Ciu.png") center/contain no-repeat!important;filter:drop-shadow(1px 1px 0 rgba(80,50,70,0.4)) drop-shadow(-0.5px -0.5px 0 rgba(255,240,245,0.9))!important;opacity:1!important;pointer-events:none!important}
#chat .mes .mes_text blockquote{position:relative;margin:15px 0 25px!important;padding:0 35px!important;border:none!important;background:transparent!important;color:#b582a0!important;font-style:italic}
#chat .mes .mes_text blockquote::before{content:"“";position:absolute;left:5px;top:-10px;font-size:35px;color:#f0d0e4;line-height:1}
#chat .mes .mes_text blockquote::after{content:"”";position:absolute;right:5px;bottom:-12px;font-size:35px;color:#f0d0e4;line-height:1}
#chat .mes .mes_text pre,.mes_reasoning pre{background:#fdf5f9!important;color:#6b4c5c!important;border:1px dashed #fbe5f0!important;box-shadow:2px 2px 0 rgba(0,0,0,.02)!important;margin:15px 0!important;padding:25px 12px 12px 12px!important;position:relative!important;overflow-x:auto!important;border-radius:6px!important}
#chat .mes .mes_text pre::before,.mes_reasoning pre::before{content:'黎明中，燃烧着耐心，我们踏入绚烂之城。'!important;position:absolute!important;top:0!important;left:0!important;background:#f5e8f0 url("https://iili.io/BSW9Ciu.png") no-repeat 6px 50%/10px!important;padding:2px 10px 2px 20px!important;font-size:10px!important;color:#b582a0!important;border-right:1px dashed #fbe5f0!important;border-bottom:1px dashed #fbe5f0!important;border-radius:6px 0 6px 0!important}
#chat .mes .mes_text pre code,.mes_reasoning pre code{background:transparent!important;color:#6b4c5c!important;text-shadow:none!important}
#chat .mes .mes_text :not(pre)>code{background:#f5e8f0!important;color:#b582a0!important;padding:2px 5px!important;border-radius:4px!important}

/* 7.2 思维链 - 粉紫 */
.mes_reasoning_details{margin:15px 0!important;border:none!important;background:transparent!important}
.mes_reasoning_header_title{display:none!important}
.mes_reasoning_header,.mes_reasoning_summary,details.mes_reasoning_details>summary,.mes_reasoning_header_text{background:transparent!important;box-shadow:none!important}
.mes_reasoning_summary{display:flex!important;justify-content:center!important;align-items:center!important;border-top:1px dashed #fbe5f0!important;border-bottom:1px dashed #fbe5f0!important;padding:8px 30px!important;color:#c9a0bc!important;font-size:12px!important;letter-spacing:2px!important;list-style:none!important}
.mes_reasoning_summary::-webkit-details-marker,.mes_reasoning_header_icon{display:none!important}
/* 🤍这里设置你的文字 */
.mes_reasoning_header::before{content:"你隐没在梦中 宛如雪化在火中"!important}
.mes_reasoning{background:rgba(200,160,180,.05)!important;color:#b582a0!important;font-size:.85em!important;font-style:italic!important;line-height:1.8!important;padding:15px!important;border:none!important;border-left:2px solid #e8c8dc!important;border-radius:4px!important}

/* 8.UI修复 - 粉紫全局适配 */
.standoutHeader,.title_restorable,.inline-drawer-header,#user-settings-block h4,h4[data-i18n],.persona_management_global_settings h4{background-color:#fff9fc!important;background-image:none!important;border:1px solid #f5dce8!important;color:#6b4c5c!important;border-radius:6px!important;text-shadow:none!important}
.text_pole,textarea,select,.drawer-content,.menu_button,#completion_prompt_manager_list .completion_prompt_manager_prompt_name{background-color:#fff9fc!important;border:1px solid #f0d0e4!important;color:#6b4c5c!important;border-radius:6px!important}
.range-block-counter input,.neo-range-input{background-color:#fff9fc!important;border:1px solid #f0d0e4!important;color:#6b4c5c!important;border-radius:4px!important}
#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *{color:#b582a0!important;-webkit-text-fill-color:#b582a0!important;text-shadow:none!important;opacity:1!important}
.text_pole:focus,textarea:focus,select:focus{border-color:#e0b8d0!important;box-shadow:0 0 0 2px rgba(200,160,180,0.2)!important;outline:none!important}
.menu_button:hover{background-color:#fdf0f6!important;color:#6b4c5c!important}

/* 9.底栏顶栏精修：粉紫悬浮岛 */
#send_form{width:94%!important;max-width:860px!important;margin:0 auto 15px auto!important;background:transparent!important;border-radius:12px!important;border:none!important;box-shadow:none!important;position:relative!important}
#nonQRFormItems{position:relative!important;border-radius:12px!important}
#send_textarea{background:transparent!important;border:none!important;box-shadow:none!important;color:#6b4c5c!important}
#send_textarea::placeholder{color:transparent!important}
#leftSendForm>div,#rightSendForm>div{transform:scale(0.8)!important;transform-origin:center!important}
#options_button,#send_but,#mes_stop,.stscript_btn,#mes_impersonate,#mes_continue{color:#d9b8d0!important;transition:color .2s ease!important}
#options_button:hover,#send_but:hover,#mes_stop:hover,.stscript_btn:hover,#mes_impersonate:hover,#mes_continue:hover{color:#b582a0!important}
/* 🤍 自定义占位符文字 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::after{content:"「蔷 薇」";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);color:#c9a0bc;font-size:15px;font-style:italic;letter-spacing:4px;pointer-events:none;z-index:10}
#qr--bar{max-height:0;opacity:0;overflow:hidden;transition:.3s ease;pointer-events:none;border-radius:12px!important}
#send_form:focus-within #qr--bar{max-height:150px;opacity:1;pointer-events:auto;margin-bottom:5px}
#top-bar{height:34px!important;min-height:34px!important;background-color:transparent!important;box-shadow:none!important;border-bottom:none!important;display:flex!important;align-items:center!important;justify-content:center!important;padding:0!important;overflow:hidden!important}
.drawer-toggle{height:34px!important;width:44px!important;display:flex!important;align-items:center!important;justify-content:center!important;cursor:pointer!important;-webkit-tap-highlight-color:transparent}
/* 🤍 顶栏图标粉紫阴影 */
.drawer-icon{font-size:0!important;display:block!important;width:18px!important;height:18px!important;background:url("https://iili.io/BSW9Ciu.png") center/contain no-repeat!important;opacity:1!important;transition:transform .6s cubic-bezier(.34,1.56,.64,1)!important}
.drawer-toggle:hover .drawer-icon{transform:scale(1.1)!important;filter:drop-shadow(2px 3px 4px rgba(130,80,110,0.4))!important}
.drawer-toggle:active .drawer-icon{transform:scale(.9) rotate(360deg)!important;transition:transform .4s!important}
.drawer-icon *{display:none!important}
.top-bar-border{display:none!important}

/* 10.移动端响应式 - 粉紫 */
@media screen and (max-width:800px){
#chat .mes{width:92%!important;padding:25px 20px 30px 40px!important;margin-left:auto!important;margin-right:auto!important;overflow:visible!important}
#chat .mes .mes_block{padding-left:15px!important}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{top:145px!important;font-size:10px!important}
#chat .mes .tokenCounterDisplay{right:25px!important}
#chat .mes .mes_timer{right:80px!important}
#chat .mes .mesIDDisplay{right:135px!important}
#chat .mes .mes_block::before{height:130px;margin-bottom:25px}
#chat .mes::before{left:4px!important;width:28px!important}
#chat .mes .avatar{top:120px!important;left:75px!important;width:60px!important;height:60px!important}
#chat .mes .ch_name{margin-left:85px!important}
#chat .mes .name_text{font-size:17px!important}
#chat .mes .ch_name>.flex-container.flex1::after{font-size:12px;margin-top:4px}
#chat .mes .mes_buttons{bottom:15px!important;right:20px!important}
#chat .mes .mes_edit_buttons{right:20px!important;bottom:40px!important}
#chat .mes .mes_text{margin-top:25px!important;font-size:14px!important}
}

/* 12.通知弹窗(Toast)适配：粉紫脚注风格 */
#toast-container>.toast{background-image:none!important;background-color:#fff9fc!important;border:1px dashed #fbe5f0!important;border-left:4px solid #e0b8d0!important;box-shadow:0 4px 15px rgba(0,0,0,.08)!important;border-radius:8px!important;color:#6b4c5c!important;padding:15px 20px 15px 50px!important;opacity:1!important;font-size:14px!important}
#toast-container>.toast::before{content:""!important;position:absolute!important;left:15px!important;top:50%!important;transform:translateY(-50%)!important;width:24px!important;height:24px!important;background:url("https://iili.io/BSW9Ciu.png") center/contain no-repeat!important;filter:opacity(.6)!important}
#toast-container>.toast-success,#toast-container>.toast-info,#toast-container>.toast-warning,#toast-container>.toast-error{background-color:#fff9fc!important}

body * {
  box-shadow: none !important;
  filter: none !important;
}

/* 编辑菜单 - 统一放在末尾 */
#chat .mes { position: relative !important; }
#chat .mes .mes_edit_buttons { position: absolute !important; bottom: -30px !important; right: 0 !important; background: #fff9fc !important; border: 1px solid #fbe5f0 !important; border-radius: 8px !important; padding: 8px 12px !important; box-shadow: 0 4px 15px rgba(0,0,0,0.1) !important; gap: 12px !important; flex-direction: row !important; z-index: 1000 !important; }
#chat .mes .mes_edit_buttons .menu_button { display: inline-flex !important; align-items: center !important; justify-content: center !important; color: #c9a0bc !important; background: transparent !important; border: none !important; font-size: 16px !important; width: 28px !important; height: 28px !important; padding: 0 !important; margin: 0 !important; cursor: pointer !important; }
#chat .mes .mes_edit_buttons .menu_button:hover { color: #b582a0 !important; background: rgba(200,160,180,.1) !important; border-radius: 4px !important; }
#chat .mes .mes_edit_buttons .menu_button.disabled { opacity: .4 !important; cursor: not-allowed !important; pointer-events: none !important; }
.mes_edit_buttons .menu_button::before { font-family: "Font Awesome 6 Free" !important; font-weight: 900 !important; }
.mes_edit_done::before { content: "\f00c" !important; }
.mes_edit_copy::before { content: "\f0c5" !important; }
.mes_edit_delete::before { content: "\f2ed" !important; }
.mes_edit_up::before { content: "\f077" !important; }
.mes_edit_down::before { content: "\f078" !important; }
.mes_edit_cancel::before { content: "\f00d" !important; }

/* 滑动条 - 浅粉紫 */
input[type="range"], input[type="range"]:disabled { filter: none; box-shadow: none !important; background-color: #f5e8f0 !important; height: 3px !important; }
input[type="range"]::-webkit-slider-thumb { width: 15px; height: 15px; box-shadow: none; background-color: #e0b8d0 !important; border-radius: 50%; border: none !important; outline: none !important; }
input[type="range"]::-webkit-slider-thumb:hover { background-color: #c9a0bc !important; }
input[type="range"]::-moz-range-thumb { width: 15px; height: 15px; background-color: #e0b8d0 !important; border: none !important; border-radius: 50%; }

/* 勾选框 - 浅粉紫 */
input[type="checkbox"] { -webkit-appearance: none; appearance: none; width: 18px; height: 18px; background-color: #fff9fc !important; border: 1px solid #f0d0e4 !important; border-radius: 4px; outline: none; box-shadow: none; cursor: pointer; }
input[type="checkbox"]:checked { background-color: #f0d0e4 !important; border-color: #e0b8d0 !important; position: relative; }
input[type="checkbox"]:checked::before { content: "✓"; display: block; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #c9a0bc !important; font-size: 12px; font-weight: bold; width: auto; height: auto; box-shadow: none; background: none; }

/* 头像边框 - 浅粉紫 */
#chat .mes .avatar, #chat .mes .avatar img { border: none !important; outline: none !important; }
#chat .mes .avatar { border: 4px solid #F1DBEA !important; background: #F1DBEA !important; }
/* 修复更多按钮（三点）显示问题 */
#chat .mes .mes_buttons .extraMesButtonsHint { display: inline-flex !important; align-items: center !important; justify-content: center !important; opacity: 1 !important; visibility: visible !important; }
#chat .mes .mes_buttons .extraMesButtonsHint::before { font-family: "Font Awesome 6 Free" !important; content: "\f141" !important; font-size: 18px !important; font-weight: 900 !important; color: #e0b8d0 !important; opacity: 1 !important; visibility: visible !important; }
/* 确保悬停在气泡上时才显示按钮（保持原有隐藏逻辑） */
#chat .mes .mes_buttons .mes_button { opacity: 0 !important; transition: opacity 0.2s !important; }
#chat .mes:hover .mes_buttons .mes_button { opacity: 1 !important; }
/* ================= 隐藏换页符但保留点击功能 ================= */
.mes .swipe_left,
.mes .swipe_right,
.mes .swipes-counter,
.swipeRightBlock {
    opacity: 0 !important;
    visibility: visible !important;
    pointer-events: auto !important;
}
